package com.healthbar;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(HealthbarIndicatorsConfig.CONFIG_GROUP)
public interface HealthbarIndicatorsConfig extends Config
{
	String CONFIG_GROUP = "healthbarIndicators";
	String TRACKED_EFFECTS_KEY = "trackedEffects";
	String SETUPS_KEY = "setups";
	String ACTIVE_SETUP_KEY = "activeSetup";

	@ConfigItem(
		keyName = "flashRate",
		name = "Flash Rate (ms)",
		description = "How fast icons blink on/off in milliseconds",
		position = 0
	)
	default int flashRate()
	{
		return 500;
	}

	@ConfigItem(
		keyName = "blinkIcons",
		name = "Blink Icons",
		description = "When disabled, active indicators stay continuously visible",
		position = 1
	)
	default boolean blinkIcons()
	{
		return true;
	}

	@ConfigItem(
		keyName = "iconSize",
		name = "Icon Size",
		description = "Size of indicator icons in pixels",
		position = 2
	)
	default int iconSize()
	{
		return 20;
	}

	@Range(min = 0, max = 100)
	@ConfigItem(
		keyName = "zoomDamping",
		name = "Zoom Sensitivity %",
		description = "How much icons scale with zoom (0 = no scaling, 100 = full scaling)",
		position = 3
	)
	default int zoomDamping()
	{
		return 0;
	}

	@ConfigItem(
		keyName = "invertZoomScaling",
		name = "Invert Zoom Scaling",
		description = "When enabled, icons grow when zooming out (like the healthbar). Warning: moving the camera while indicators are visible can make icons grow choppily.",
		position = 4
	)
	default boolean invertZoomScaling()
	{
		return false;
	}

	@Range(min = -500, max = 500)
	@ConfigItem(
		keyName = "offsetX",
		name = "X Offset",
		description = "Horizontal offset in pixels (negative = left, positive = right)",
		position = 5
	)
	default int offsetX()
	{
		return 0;
	}

	@Range(min = -500, max = 500)
	@ConfigItem(
		keyName = "offsetY",
		name = "Y Offset",
		description = "Vertical offset in pixels (negative = down, positive = up)",
		position = 6
	)
	default int offsetY()
	{
		return 0;
	}

	@ConfigSection(
		name = "Prayer Point Bar",
		description = "Display current prayer points below your character's health bar",
		position = 7
	)
	String PRAYER_BAR_SECTION = "prayerPointBar";

	@ConfigItem(
		keyName = "showPrayerPointBar",
		name = "Show Prayer Point Bar",
		description = "Show a light-blue prayer point bar below your health bar, across all setups",
		section = PRAYER_BAR_SECTION,
		position = 0
	)
	default boolean showPrayerPointBar()
	{
		return false;
	}

	@ConfigItem(
		keyName = "prayerBarOnlyWithHealthBar",
		name = "Only with health bar",
		description = "When enabled, show only while health-bar data is available. Disable to always show during gameplay.",
		section = PRAYER_BAR_SECTION,
		position = 1
	)
	default boolean prayerBarOnlyWithHealthBar()
	{
		return true;
	}

	@Range(min = 0, max = 99)
	@ConfigItem(
		keyName = "prayerBarWarningThreshold",
		name = "Low prayer threshold",
		description = "Flash the depleted portion red below this many prayer points (0 disables). Uses Flash Rate (ms).",
		section = PRAYER_BAR_SECTION,
		position = 2
	)
	default int prayerBarWarningThreshold()
	{
		return 10;
	}

	@ConfigItem(
		keyName = TRACKED_EFFECTS_KEY,
		name = "",
		description = "",
		hidden = true
	)
	default String trackedEffects()
	{
		return "[]";
	}

	@ConfigItem(
		keyName = TRACKED_EFFECTS_KEY,
		name = "",
		description = ""
	)
	void setTrackedEffects(String json);
}
